// RootHelperServer is the server API for RootHelper service.
// All implementations must embed UnimplementedRootHelperServer
// for forward compatibility.
type RootHelperServer interface {
	// Version says which helper this is and what it serves. Every helper
	// serves it, so it is the agent's handshake.
	Version(context.Context, *VersionRequest) (*VersionResponse, error)
	// EnsureHost makes sure the host's firewall is set up for sandboxes:
	// bridged traffic through netfilter, the sandboxes' rule chain and its
	// block sets, and the IPv6 fence on the sandboxes' bridge, all from the
	// helper's own settings. It starts the helper's own timer that puts them,
	// and the node guard and floor, back if something takes them away, and
	// answers whether the IPv6 fence covers the sandboxes now.
	EnsureHost(context.Context, *EnsureHostRequest) (*EnsureHostResponse, error)
	// EnsureHostFiles makes sure a container's hostname, hosts and
	// resolv.conf files (and the egress CA, when asked) exist with this
	// content, and drops an egress CA the request no longer asks for.
	EnsureHostFiles(context.Context, *EnsureHostFilesRequest) (*EnsureHostFilesResponse, error)
	// EnsureTaskFIFOs makes fresh stdout and stderr FIFOs for a container's
	// next task, at that container's fixed paths. Call it once per task,
	// before opening them: a task's old readers keep the old FIFOs.
	EnsureTaskFIFOs(context.Context, *EnsureTaskFIFOsRequest) (*EnsureTaskFIFOsResponse, error)
	// EnsureRunscConfig makes sure one of the runsc shim configs the helper
	// owns exists. The helper writes its whole content.
	EnsureRunscConfig(context.Context, *EnsureRunscConfigRequest) (*EnsureRunscConfigResponse, error)
	// EnsureReadySocket gives the agent's ready socket for a container a
	// name in the helper's folder, for the spec to bind. The agent binds and
	// keeps the socket in its own ready folder, as before; the helper links
	// that socket into its own folder and checks, after linking, that it is
	// a socket the agent owns.
	EnsureReadySocket(context.Context, *EnsureReadySocketRequest) (*EnsureReadySocketResponse, error)
	// RemoveContainerFiles makes sure everything the helper made for a
	// container is gone: host files, FIFOs and ready socket names.
	RemoveContainerFiles(context.Context, *RemoveContainerFilesRequest) (*RemoveContainerFilesResponse, error)
	// EnsureHostNetwork makes sure the host is ready for sandbox networks:
	// IP forwarding on, and the helper's CNI config written when absent. It
	// answers with the sandboxes' address range that config hands out.
	EnsureHostNetwork(context.Context, *EnsureHostNetworkRequest) (*EnsureHostNetworkResponse, error)
	// RealizeNetns makes sure a sandbox's network namespace exists, with
	// loopback up, IPv6 off and an address on the sandboxes' bridge, and
	// answers with its path and address. A namespace already realized is
	// answered as it is.
	RealizeNetns(context.Context, *RealizeNetnsRequest) (*RealizeNetnsResponse, error)
	// RemoveNetns makes sure a sandbox's network namespace is gone, with its
	// CNI attachment, address lease, NAT chain and connection tracking.
	RemoveNetns(context.Context, *RemoveNetnsRequest) (*RemoveNetnsResponse, error)
	// DisableNetnsIPv6 makes sure IPv6 is off inside a realized namespace.
	DisableNetnsIPv6(context.Context, *DisableNetnsIPv6Request) (*DisableNetnsIPv6Response, error)
	// NetnsAddrs says whether a namespace exists and lists its IPv4
	// addresses, loopback aside: the address a task started there has.
	NetnsAddrs(context.Context, *NetnsAddrsRequest) (*NetnsAddrsResponse, error)
	// SetNodeGuard makes sure the node guard (the node closed to the
	// sandboxes' range) holds, with these ports open, and puts it back if
	// something took it away.
	SetNodeGuard(context.Context, *SetNodeGuardRequest) (*SetNodeGuardResponse, error)
	// SetEgressFloor makes sure the node-wide deny floor holds these
	// networks, plus the cloud metadata endpoints the helper always adds.
	SetEgressFloor(context.Context, *SetEgressFloorRequest) (*SetEgressFloorResponse, error)
	// SandboxRules changes one sandbox address's rules.
	SandboxRules(context.Context, *SandboxRulesRequest) (*SandboxRulesResponse, error)
	// PrepareSandbox does a create's root work in one call: each part the
	// request lists (see VersionResponse.parts). A helper refuses a request
	// that carries a part, or a field, it does not know, so nothing is ever
	// skipped without a word. The cgroup part comes alone, once the
	// sandbox's task has started: the runtime makes its group with the task,
	// after the namespace and rules of the create's first call. The
	// container's parts (files) come together, named by container_id, just
	// before the container is made, and again before each start.
	PrepareSandbox(context.Context, *PrepareSandboxRequest) (*PrepareSandboxResponse, error)
	// ReleaseSandbox undoes PrepareSandbox: the address's rules first, then
	// its namespace and attachment. Its files part, alone and named by
	// container_id, removes everything the helper made for the container.
	ReleaseSandbox(context.Context, *ReleaseSandboxRequest) (*ReleaseSandboxResponse, error)
	// The hostname egress gateway's host side (M1 PR 5b). BridgeProbe builds,
	// drives and removes the gateway self-test's probe network on the
	// helper's own bridge; MatchProcess answers which of a sandbox's listed
	// executables holds one connection (per-binary egress rules).
	BridgeProbe(context.Context, *BridgeProbeRequest) (*BridgeProbeResponse, error)
	MatchProcess(context.Context, *MatchProcessRequest) (*MatchProcessResponse, error)
	// HostPort forwards raw-TCP host ports of this node in the kernel, for
	// ingress proxy routing (plans/ingress-proxy-routing.md §3.5; M1 PR 5b),
	// as sandboxd's hostport.Forwarder does in privilege mode single: sets
	// one port's forward, removes one, or makes the node's set exactly a
	// list. The helper takes only ports of its own host-port range, and
	// hands them only to a leased sandbox address, another node's host port,
	// or sandboxd's own listener.
	HostPort(context.Context, *HostPortRequest) (*HostPortResponse, error)
	// MountExternal makes sure a sandbox's mounts serve, and answers with
	// their mount points for the container's binds.
	MountExternal(context.Context, *MountExternalRequest) (*MountExternalResponse, error)
	// UnmountExternal makes sure a sandbox's mounts are gone: its tools
	// stopped, its mounts unmounted, its folder, key files and caches
	// removed.
	UnmountExternal(context.Context, *UnmountExternalRequest) (*UnmountExternalResponse, error)
	// SweepExternalMounts removes the mounts of every sandbox the request
	// does not keep, except those a call is working on.
	SweepExternalMounts(context.Context, *SweepExternalMountsRequest) (*SweepExternalMountsResponse, error)
	// ReclaimVolume deletes a deleted platform volume's files on the NFS
	// export of the helper's own settings (SB_PLATFORM_VOLUMES_NFS_*): it
	// mounts the volume's folder in a scratch folder of its own, nosuid,
	// nodev and noexec, empties it without crossing into another mount or
	// following a link, and unmounts it. The source must be one volume's
	// folder of that export, <server>:/<export>/<scope>/<name>.
	ReclaimVolume(context.Context, *ReclaimVolumeRequest) (*ReclaimVolumeResponse, error)
	// PrepareHost makes sure what a host needs before its process starts
	// exists: a V8 group's jail (its chroot, linked from the helper's base
	// tree, with a run folder the agent writes its config and sockets into).
	PrepareHost(context.Context, *PrepareHostRequest) (*PrepareHostResponse, error)
	// SpawnHost makes sure a host runs, and answers with its process. A host
	// that already runs is answered as it is.
	SpawnHost(context.Context, *SpawnHostRequest) (*SpawnHostResponse, error)
	// StopHost makes sure a host is gone: every process in its group killed,
	// and what PrepareHost and SpawnHost made removed.
	StopHost(context.Context, *StopHostRequest) (*StopHostResponse, error)
	// ListHosts lists the hosts the helper holds anything for, read from the
	// kernel: those whose process runs, and those left with none (pid 0),
	// for the agent's sweep.
	ListHosts(context.Context, *ListHostsRequest) (*ListHostsResponse, error)
	// SetHostLimits changes a running host's limits (a warm V8 group host a
	// tenant claims takes that tenant's).
	SetHostLimits(context.Context, *SetHostLimitsRequest) (*SetHostLimitsResponse, error)
	// EnsureTap makes sure one of the TAP pool's devices is up: made for the
	// jailer's user, with the host's address of its slot, strict reverse
	// path filtering, IPv6 off and the guest's neighbor entry. The helper
	// works the slot's addresses out from the name and its own TAP base; on
	// its first TAP it also puts in the guests' NAT and isolation.
	EnsureTap(context.Context, *EnsureTapRequest) (*EnsureTapResponse, error)
	// RemoveTap makes sure one of the pool's TAP devices is gone.
	RemoveTap(context.Context, *RemoveTapRequest) (*RemoveTapResponse, error)
	// MakeFilesystem makes an ext4 filesystem in one of a VM's disk files, in
	// its jail's stage folder: the root disk, from a folder of the agent's,
	// or the overlay disk, empty. mkfs.ext4 runs as the agent's own user,
	// seen as root in a user namespace of its own, so the files come out
	// owned by root as in privilege mode single and it can read and write
	// nothing the agent could not.
	MakeFilesystem(context.Context, *MakeFilesystemRequest) (*MakeFilesystemResponse, error)
	// EnsureGuestFirewall makes sure the guests' firewall is set up: the
	// guests' NAT and isolation (as EnsureTap puts them in), their rule chain
	// and block sets, and the floor. It starts the helper's own timer that
	// puts them back if something takes them away.
	EnsureGuestFirewall(context.Context, *EnsureGuestFirewallRequest) (*EnsureGuestFirewallResponse, error)
	// SetGuestNodeGuard makes sure the node guard holds for the TAP base,
	// with these ports open. The ports are the ones SetNodeGuard takes.
	SetGuestNodeGuard(context.Context, *SetNodeGuardRequest) (*SetNodeGuardResponse, error)
	// SetGuestEgressFloor makes sure the deny floor for the TAP base holds
	// these networks, plus the cloud metadata endpoints the helper always
	// adds.
	SetGuestEgressFloor(context.Context, *SetEgressFloorRequest) (*SetEgressFloorResponse, error)
	// GuestRules changes one guest address's rules.
	GuestRules(context.Context, *GuestRulesRequest) (*GuestRulesResponse, error)
	// ShareFirecrackerFiles links files the agent built in the VM's stage
	// folder into its chroot, read-only for the jailer's user: a snapshot's
	// memory and state, and a template's root disk, which a snapshot load
	// attaches read-only. Each must be the agent's own regular file; it
	// stays the agent's, with the jailer's group and mode 0640. The VM's
	// process must run (a chroot is made again from nothing before it
	// starts).
	ShareFirecrackerFiles(context.Context, *FirecrackerFilesRequest) (*FirecrackerFilesResponse, error)
	// HandOutFirecrackerFiles lets the agent's group read files in the VM's
	// chroot that the VM made or writes: a snapshot's memory and state, its
	// disks. Each must be a regular file of the jailer's user with one name
	// (or one the helper shared, which is the agent's already); the helper
	// sets its group to the agent's and its mode to 0640. The agent copies
	// it out, with checks of its own.
	HandOutFirecrackerFiles(context.Context, *FirecrackerFilesRequest) (*FirecrackerFilesResponse, error)
	// GrantWasmMounts lends a WASM sandbox's external mounts to the WASM
	// host that serves it (M1 PR 15). A WASM guest reaches a mount through
	// its mount point, opened and passed to its host as a folder. In
	// privilege mode single sandboxd does that as root; in split it cannot
	// reach the helper's mount points, so the helper does. The agent names
	// the sandbox and the host, never a path: the helper asks the host, on
	// the socket it serves the host on, whether it holds that sandbox, and
	// only then opens each of the sandbox's mount points it holds itself,
	// by the path it built, without entering the mount, and passes them
	// over the same socket. Safe to retry and to repeat: a later loan
	// replaces an earlier one.
	GrantWasmMounts(context.Context, *GrantWasmMountsRequest) (*GrantWasmMountsResponse, error)
	mustEmbedUnimplementedRootHelperServer()
}

